import json, time, urllib.request, urllib.error, sys, collections
BASE = "http://localhost:8080"
tok = None
log = collections.Counter()
events = []

def new_token():
    global tok
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                tok = json.load(r)["token"]; log["token"] += 1; return
        except urllib.error.HTTPError as e:
            handle_err(e, "/token")
        except Exception as e:
            log["tokexc"] += 1; time.sleep(1)

def handle_err(e, path):
    log[f"http{e.code}"] += 1
    body = e.read()[:300]
    events.append((path, e.code, dict(e.headers), body.decode(errors="replace")))
    if e.code == 429:
        ra = e.headers.get("Retry-After")
        time.sleep(float(ra) if ra else 1)
    elif e.code == 401:
        new_token()
    else:
        time.sleep(0.5)

def get(path):
    if tok is None: new_token()
    for attempt in range(200):
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                raw = r.read()
                try:
                    return json.loads(raw)
                except Exception:
                    log["badjson"] += 1; events.append((path, "badjson", None, raw[:300].decode(errors="replace"))); time.sleep(0.5)
        except urllib.error.HTTPError as e:
            if e.code == 404 and path.startswith("/customers/"):
                return None
            handle_err(e, path)
        except Exception as e:
            log["exc:" + type(e).__name__] += 1; events.append((path, repr(e), None, None)); time.sleep(0.5)
    raise RuntimeError("gave up " + path)

pages = {}
d = get("/orders?page=1"); pages[1] = d
total = d["total_pages"]
nexts = {1: d["next"]}
for p in range(2, total + 1):
    pages[p] = get(f"/orders?page={p}")
    nexts[p] = pages[p]["next"]
# follow next from last page to check nothing beyond
json.dump({"pages": pages, "nexts": nexts}, open("/tmp/recon/pages.json", "w"))
ids = sorted({o["customer_id"] for pg in pages.values() for o in pg["items"]})
custs = {}
for c in ids:
    custs[c] = get(f"/customers/{c}")
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print(dict(log))
json.dump(events, open("/tmp/recon/events.json", "w"), default=str)
EOF
python3 -I /tmp/recon/fetch.py

